        final Set<Entity> existing=Collections.newSetFromMap(new IdentityHashMap<>()),mine=Collections.newSetFromMap(new IdentityHashMap<>());final List<ItemEntity> tokens=new ArrayList<>();final Set<Long> forced=new HashSet<>();final Map<Entity,Vec3> frozen=new IdentityHashMap<>();
        final boolean mobDrops;final int alphaKills,betaKills;int phase,lastTick,wait;ItemEntity stack,paused,unloaded;
        State(GameController game){this.game=game;level=game.maps().level();alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));beta=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));require(game.playing()&&alpha!=null&&beta!=null&&game.allowDamage(beta),"actual match participants");alphaState=new GameChecks.WandThirdPlayerState(alpha,game.items().mana());betaState=new GameChecks.WandThirdPlayerState(beta,game.items().mana());origin=new Vec3(Math.floor(alpha.getX()/16)*16+8.37,245.7,Math.floor(alpha.getZ()/16)*16+8.81);level.getAllEntities().forEach(existing::add);mobDrops=level.getGameRules().get(GameRules.MOB_DROPS);alphaKills=kills(alpha);betaKills=kills(beta);}
