        List<Entity> batch(LbcCreatureDropItem.Kind kind){clear();var t=drop(kind,2);t.setTarget(beta.getUUID());t.setYRot(37);t.setXRot(23);require(game.items().creatureDrops().ready(t,runtime(kind)),"loaded admission "+kind);require(game.items().specialDrops().spawn(t)&&t.getItem().getCount()==1,"shared one debit "+kind);require(!game.items().specialDrops().spawn(t),"same tick guard");capture();var out=new ArrayList<>(mine);out.sort(Comparator.comparingInt(Entity::getId));if(kind==LbcCreatureDropItem.Kind.OLD_VEX)require(Math.abs(net.minecraft.util.Mth.wrapDegrees(t.getYRot()-325))<1e-4,"source rotates item four times to288degrees");t.discard();for(var e:out)require(game.items().creatureDrops().owner(e)==alpha&&game.items().currentEpoch(e),"actual author independent pickup target");return out;}
        void presentation(){for(var kind:LbcCreatureDropItem.Kind.values()){var s=new ItemStack(kind.item());var tag=s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();require(tag.size()==2&&tag.getIntOr(kind.flag(),0)==1&&tag.getIntOr("drop",0)==1,"source token flags "+kind);boolean normal=kind==LbcCreatureDropItem.Kind.BULLETS;require(Identifier.parse(normal?"lbc:drop_trap":"minecraft:barrier").equals(s.get(DataComponents.ITEM_MODEL)),"native model "+kind);if(normal){var name=s.get(DataComponents.CUSTOM_NAME);var lore=s.get(DataComponents.LORE);require(Identifier.parse("lbc:tier_ff").equals(s.get(DataComponents.TOOLTIP_STYLE))&&name!=null&&!name.getStyle().isItalic()&&name.getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents tr&&tr.getKey().equals("trap_shulker")&&name.getStyle().getColor().getValue()==0xffff55&&lore!=null&&lore.lines().size()==1&&!lore.lines().getFirst().getStyle().isItalic()&&lore.lines().getFirst().getStyle().getColor().getValue()==0xffffff,"normal exact name/lore/tier");}else require(!s.has(DataComponents.CUSTOM_NAME)&&s.getOrDefault(DataComponents.LORE,net.minecraft.world.item.component.ItemLore.EMPTY).lines().isEmpty()&&!s.has(DataComponents.TOOLTIP_STYLE),"plain legacy token");String leaf=switch(kind){case OLD_VEX->"old_vex_drop";case OLD_SKELETON->"old_skeleton_drop";case BULLETS->"shulker_bullets_drop";case BULLETS_OLD->"shulker_bullets_drop_old";};var loot=game.lbc().rollTable(level,origin,alpha,"lbc:ported/"+leaf);require(loot.size()==1&&ItemStack.isSameItemSameComponents(s,loot.getFirst()),"public leaf prototype "+kind);}for(var item:List.of(Items.BARRIER,Items.REPEATING_COMMAND_BLOCK,Items.PAPER))require(!LbcCreatureDropItem.matches(new ItemStack(item)),"unflagged lookalike rejected");}
