        void guards(Entity actor,boolean wild){for(String role:List.of("spectator","rcdenyalways","sauvojen_tuntija","strict_map_object","magic_academy","transformator")){var victim=cow();victim.entityTags().add(role);try{require(!game.items().creatureDrops().canAffect(actor,victim)&&!game.items().creatureDrops().canTarget(actor,victim),"role guards "+role);}finally{victim.discard();}}var board=game.server().getScoreboard();var oldA=alpha.getTeam();var oldB=beta.getTeam();require(board.getPlayerTeam("codex_creature_probe")==null,"fixture team available");var team=board.addPlayerTeam("codex_creature_probe");team.setAllowFriendlyFire(false);try{board.addPlayerToTeam(alpha.getScoreboardName(),team);board.addPlayerToTeam(beta.getScoreboardName(),team);require(game.items().creatureDrops().canAffect(actor,beta)==wild&&game.items().creatureDrops().canTarget(actor,beta)==wild,"mob ally protection versus WILD bullet");require(game.items().creatureDrops().canAffect(actor,alpha),"actual author source eligible");if(wild){reset(beta);float hp=beta.getHealth();hit(actor,beta);require(beta.getHealth()<hp&&beta.hasEffect(net.minecraft.world.effect.MobEffects.LEVITATION),"actual WILD allied bullet hit");beta.removeAllEffects();beta.setHealth(1000);}}finally{board.removePlayerTeam(team);if(oldA!=null)board.addPlayerToTeam(alpha.getScoreboardName(),oldA);if(oldB!=null)board.addPlayerToTeam(beta.getScoreboardName(),oldB);}}
